    // SDK::FindClass/FindEnum/FindStruct walk the whole object array on every call. The bot
    // code calls them many times per bot per frame; on Season 6+ several names are missing
    // or sit far down the array, which alone cost ~2 ms per bot per frame. Remember results
    // (misses are retried every 15 seconds in case the asset loads later).
    template<typename T,typename F> inline const T* SyndicateCachedLookup(const char* Name,F&& Find){
        static std::unordered_map<std::string,std::pair<const T*,ULONGLONG>> Cache;
        const auto Now=GetTickCount64();auto It=Cache.find(Name);
        if(It!=Cache.end() && (It->second.first || Now<It->second.second))return It->second.first;
        auto Found=(const T*)Find(Name);Cache[Name]={Found,Now+15000};return Found;
    }
    // Builds whose OnlineEngineInterface factory creates real bot IDs (distinct names in game).
    inline bool NativeBotIdBuild(){const auto V=VersionInfo.FortniteVersion;return V==1.11||V==2.5||V==3.5||V==4.0||V==4.5||V==5.10||V==6.20;}
    inline bool GuardedIdFactory(void* Factory,const UObject* Online,void* Shared,const FString* Text,uint64 Type){
        __try{((void*(*)(const UObject*,void*,const FString*,uint64))Factory)(Online,Shared,Text,Type);return true;}
        __except(EXCEPTION_EXECUTE_HANDLER){return false;}
    }
    inline const UClass* FindClass(const char* Name){return SyndicateCachedLookup<UClass>(Name,[](const char* N){return SDK::FindClass(N);});}
    inline const UEnum* FindEnum(const char* Name){return SyndicateCachedLookup<UEnum>(Name,[](const char* N){return SDK::FindEnum(N);});}
    inline const UStruct* FindStruct(const char* Name){return SyndicateCachedLookup<UStruct>(Name,[](const char* N){return SDK::FindStruct(N);});}
