    inline UFortHealthSet* BotHealthSet(AFortPlayerPawnAthena* Pawn)
    {
        if(!Pawn)return nullptr;
        auto O=Pawn->GetOffset("HealthSet");
        if(O!=uint32(-1))if(auto Set=GetFromOffset<UFortHealthSet*>(Pawn,O))return Set;
        auto State=Pawn->PlayerState;
        auto AO=State?State->GetOffset("AbilitySystemComponent"):uint32(-1);
        auto ASC=AO!=uint32(-1)?GetFromOffset<UObject*>(State,AO):nullptr;
        auto SO=ASC?ASC->GetOffset("SpawnedAttributes"):uint32(-1);
        auto Class=FindClass("FortHealthSet");
        if(SO!=uint32(-1) && Class)for(auto Set:GetFromOffset<TArray<UObject*>>(ASC,SO))if(Set && Set->IsA(Class))return (UFortHealthSet*)Set;
        return nullptr;
    }
