    inline std::unordered_set<std::wstring>& MissingBotAssets(){static std::unordered_set<std::wstring> Set;return Set;}
    // Server frame timing split, filled by the net driver tick (NetDriver.cpp).
    // Match pacing telemetry (per storm phase): see "match report" lines in the bot log.
    inline int StatStormDeaths=0,StatCombatDeaths=0,StatBuildOk=0,StatBuildFail=0,StatStuck=0;
    inline int StatHold=0,StatMobility=0,StatEdits=0,StatHeals=0,StatSurgeHits=0,StatFallDeaths=0,StatTunnel=0;
