    inline std::unordered_map<AFortPlayerStateAthena*,float> SurgeDamage;inline bool SurgeActive=false;inline float SurgeCut=0;
    inline void SurgeCredit(AFortPlayerStateAthena* S,float D){if(S && std::isfinite(D) && D>0)SurgeDamage[S]+=D;}
    inline double PerfBotMs=0,PerfRepMs=0;inline unsigned PerfFrames=0;inline const char* PerfRepPath="?";
    // Syndicate perf: look in memory first. StaticLoadObject on every bot cosmetic/weapon
    // lookup forced "Flushing async loaders" ~750 times per match on the host, and
    // each flush stalls the server frame (felt as lag spikes / rubber-banding).
    inline const UObject* LoadBotAsset(const wchar_t* Path,const UClass* Class){
        if(!BotAssetAvailable(Path))return nullptr;
        if(auto Loaded=SDK::FindObject(Path,Class))return Loaded;
        if(MissingBotAssets().count(Path))return nullptr;
        auto Loaded=SDK::StaticLoadObject(Path,Class);
        if(!Loaded)MissingBotAssets().insert(Path);
        return Loaded;
    }
