    inline bool FiftyTeamMode(){return VersionInfo.FortniteVersion>=4 && VersionInfo.FortniteVersion<5 && std::wstring(FConfiguration::Playlist).find(L"Playlist_50v50")!=std::wstring::npos;}
    inline bool FiftyWaitForApproach(float Distance,float Previous,float SecondsLeft){return Distance>18000.f && (Previous<0 || Distance<Previous) && SecondsLeft>8.f;}
    inline bool FiftyLandingZone(FVector& Center,float& Radius){
        auto W=UWorld::GetWorld();auto GS=W?(AFortGameStateAthena*)W->GameState:nullptr;
        auto Z=GS && GS->HasSafeZoneIndicator()?(AFortSafeZoneIndicator*)GS->SafeZoneIndicator:nullptr;
        if(!Z || Z->bActorIsBeingDestroyed || !Z->HasNextCenter() || !Z->HasNextRadius())return false;
        Center=Z->NextCenter;Radius=Z->NextRadius;
        return std::isfinite(Center.X) && std::isfinite(Center.Y) && std::isfinite(Radius) && Radius>1000;
    }
    // Late game (TILTED_LATE_GAME): the bus makes one short pass over the late-game circle, so the bots land inside
    // that circle like 50v50 bots do, instead of flying to their usual towns out in the storm.
    inline bool LateGameDrop(){return FConfiguration::bLateGame;}
    inline bool CircleDropMode(){return FiftyTeamMode() || LateGameDrop();}
    inline bool CircleLandingZone(FVector& Center,float& Radius){
        // Late game: the circle the bus pass was laid out over (the storm indicator may still show the first circle).
        if(LateGameDrop() && FConfiguration::bLateGameCenterSet){Center=FVector{};Center.X=FConfiguration::LateGameCenterX;Center.Y=FConfiguration::LateGameCenterY;Radius=FConfiguration::LateGameZone>=4?10000.f:15000.f;return true;} // 4th circle is smaller
        if(FiftyLandingZone(Center,Radius))return true;
        if(!LateGameDrop())return false;
        // The storm may not be up yet while the bus is parked: the bus itself is over the circle's centre.
        auto W=UWorld::GetWorld();auto GS=W?(AFortGameStateAthena*)W->GameState:nullptr;if(!GS)return false;
        AFortAthenaAircraft* Air=GS->HasAircrafts()?(GS->Aircrafts.Num()>0?GS->Aircrafts[0]:nullptr):(GS->HasAircraft()?GS->Aircraft:nullptr);
        if(!Air || Air->bActorIsBeingDestroyed)return false;
        Center=Air->K2_GetActorLocation();Center.Z=0;Radius=12000.f;return true;
    }
    inline bool TeamKnocksEnabled()
    {
        auto World=UWorld::GetWorld();
        auto Mode=World?(AFortGameMode*)World->AuthorityGameMode:nullptr;
        // 4.00 does not expose the later GameMode DBNO flag. Use the server-selected playlist.
        if(SharedBotSeason()){
            std::wstring Playlist=FConfiguration::Playlist;
            if(Playlist.find(L"Playlist_DefaultDuo")!=std::wstring::npos || Playlist.find(L"Playlist_DefaultSquad")!=std::wstring::npos)return true;
            if(Playlist.find(L"Playlist_DefaultSolo")!=std::wstring::npos)return false;
        }
        return Mode && Mode->HasbEnableDBNO() && Mode->bEnableDBNO;
    }
