    inline SyndicateExperience::Memory Experience;
    inline SyndicateReboot::Squads RebootSquads; // per-match (fresh each server process): squad reboot cards.
    inline std::filesystem::path ExperiencePath;
    inline std::atomic<bool> ExperienceSaving=false;
    inline void UpdateExperienceStore(){
        static bool Loaded=false;static ULONGLONG NextSave=0;
        if(!Loaded){
            Loaded=true;wchar_t Ready[32768]{};
            if(GetEnvironmentVariableW(L"TILTED_SERVER_READY_FILE",Ready,32768))ExperiencePath=std::filesystem::path(Ready).parent_path()/L"bot-experience-4.00.txt";
            if(!ExperiencePath.empty()){std::ifstream In(ExperiencePath);std::string Data((std::istreambuf_iterator<char>(In)),{});if(Data.size()<1024*1024)Experience.Load(Data);}
        }
        if(ExperiencePath.empty() || GetTickCount64()<NextSave || ExperienceSaving.exchange(true))return;
        NextSave=GetTickCount64()+30000;
        auto Data=Experience.Serialize();auto Path=ExperiencePath;
        std::thread([Data=std::move(Data),Path]{
            try{auto Temp=Path;Temp+=L".tmp";{std::ofstream Out(Temp,std::ios::binary|std::ios::trunc);Out<<Data;Out.flush();if(!Out){ExperienceSaving=false;return;}}
                MoveFileExW(Temp.c_str(),Path.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH);
            }catch(...){}ExperienceSaving=false;
        }).detach();
    }
