    // Early-game looting settings (BotLootPlan.h). Server-wide overrides (read once):
    //   TILTED_BOT_FREE_LOADOUT=1      old behaviour: starting supplies, first-zone gun grant, 400 materials each
    //   TILTED_BOT_EMERGENCY_GUN=1     last resort: an unarmed bot gets one gun after 180 s
    //   TILTED_BOT_START_MATS=<n>      materials of each type at landing (default 50)
    //   TILTED_BOT_LOOT_TIME=<s>       how long a bot may stay looting its POI (default 240)
    inline SyndicateLoot::Tuning LootTuning(Bot& B){
        SyndicateLoot::Tuning T;
        struct Overrides{bool Free=false,EmergencyOff=false;float Mats=-1,Time=-1;};
        static const Overrides O=[](){Overrides R;char V[64]{};
            auto Read=[&](const char* Name,float& Out){V[0]=0;if(GetEnvironmentVariableA(Name,V,sizeof(V))){char* End=nullptr;double X=strtod(V,&End);if(End!=V && std::isfinite(X))Out=float(X);}};
            Read("TILTED_BOT_START_MATS",R.Mats);Read("TILTED_BOT_LOOT_TIME",R.Time);
            V[0]=0;R.Free=GetEnvironmentVariableA("TILTED_BOT_FREE_LOADOUT",V,sizeof(V)) && V[0]=='1';
            if(GetEnvironmentVariableW(L"TILTED_BOT_SELFTEST",nullptr,0))R.Free=true; // the self-test harness checks the old grants
            V[0]=0;R.EmergencyOff=GetEnvironmentVariableA("TILTED_BOT_EMERGENCY_GUN",V,sizeof(V)) && V[0]=='0';return R;}();
        if(O.Free){T.NoFreeLoadout=false;T.StartMaterials=400;}
        if(O.EmergencyOff)T.EmergencyGun=false;
        if(O.Mats>=0)T.StartMaterials=(std::clamp)(int(O.Mats),0,999);
        if(O.Time>0)T.MaxLootTime=(std::clamp)(O.Time,30.f,900.f);
        (void)B;return T;
    }
