    inline SyndicateBotSkill::Profile TierProfile(int Tier){
        auto Profile=SyndicateBotSkill::Get(Tier);
        if(Season5Like() && Tier==2)Profile.Spread=1.8f;
        // Pre-season / Season 1 (1.7.2, 1.8.x): 2017 players missed a lot and fired slowly.
        // Wider spread and a slower trigger keep those matches season-accurate (and stop bots
        // eliminating each other within the first minutes).
        if(EarlyChapterOne()){Profile.Spread=(std::max)(Profile.Spread*2.2f,2.6f);Profile.FireInterval*=1.5f;}
        return Profile;
    }
    // Phase 8: individual playstyle sits on top of the skill tier. A tier says how WELL a bot plays;
    // a style says HOW it chooses to play. Only timing/aggression knobs, never aim or mechanics, so a
    // style can never make a bot shoot straighter - it only changes when it presses, holds or re-pushes.
    enum class BotStyle{Balanced,Aggressive,Defensive,Passive,Sniper,Shotgunner,HighGround,Rotator,ThirdParty,Count};
    struct StyleProfile{float Press;float Caution;float ThirdParty;const char* Name;};
    inline const StyleProfile& StyleTable(int S){
        static const StyleProfile T[]={
            {1.00f,1.00f,0.50f,"balanced"},
            {1.60f,0.65f,0.90f,"aggressive"},
            {0.65f,1.45f,0.35f,"defensive"},
            {0.45f,1.65f,0.20f,"passive"},
            {0.80f,1.20f,0.40f,"sniper"},
            {1.45f,0.80f,0.70f,"shotgunner"},
            {1.05f,1.05f,0.55f,"high-ground"},
            {0.85f,1.15f,0.50f,"rotator"},
            {1.20f,0.90f,1.55f,"third-party"},
        };
        return T[(S>=0&&S<int(BotStyle::Count))?S:0];
    }
    // Weighted roll: most bots play an ordinary balanced/aggressive/defensive game, specialists are rarer.
    // Mirrors a real lobby where a few players snipe or hard-rush and the rest play the middle.
    inline int ResolveStyle(unsigned r){
        int R=int(r%100);
        return R<24?int(BotStyle::Balanced):R<42?int(BotStyle::Aggressive):R<57?int(BotStyle::Defensive)
             :R<67?int(BotStyle::Passive):R<74?int(BotStyle::Sniper):R<84?int(BotStyle::Shotgunner)
             :R<90?int(BotStyle::HighGround):R<95?int(BotStyle::Rotator):int(BotStyle::ThirdParty);
    }
    inline const StyleProfile& StyleOf(Bot& B){if(B.Style<0)B.Style=ResolveStyle(unsigned(rand()));return StyleTable(B.Style);}
    // Pushers: bots that take the fight to a real player they see instead of finishing their loot or walking off.
    // Aggressive and shotgunner styles always, third-party and balanced sometimes (harder bots more often), defensive,
    // passive and sniper never. Rolled once per bot so a lobby has a mix: some push you, others play it safe.
    inline bool IsPusher(Bot& B){
        if(B.Pusher<0){StyleOf(B);const int Tier=B.Skill<0?2:B.Skill;const int R=rand()%100;
            switch(BotStyle(B.Style)){
            case BotStyle::Aggressive: case BotStyle::Shotgunner: B.Pusher=1;break;
            case BotStyle::ThirdParty: B.Pusher=R<(Tier>=3?70:50)?1:0;break;
            case BotStyle::Balanced: case BotStyle::HighGround: B.Pusher=R<(Tier>=3?45:30)?1:0;break;
            default: B.Pusher=0;break;}
        }
        return B.Pusher==1;
    }
    inline bool IsHumanPawn(AActor* A);
    inline SyndicateBotSkill::Profile BotSkill(Bot& B){
        static int Selected=[](){char V[32]{};GetEnvironmentVariableA("TILTED_BOT_SKILL",V,sizeof(V));return SyndicateBotSkill::Parse(V);}();
        if(B.Skill<0){
            // Variety builds a realistic 99-player lobby (Phase 7): 15/30/30/20/5 across the five tiers.
            // A rolled tier 4 is a pro: advanced decisions (Skill 3) with the pro aim/reaction row via AimTier.
            if(Selected==4){int Tier=SyndicateBotSkill::ResolveVariety(unsigned(rand()));if(Tier==4){B.Skill=3;B.Pro=true;}else B.Skill=Tier;}
            else B.Skill=SyndicateBotSkill::Resolve(Selected,unsigned(rand()));
        }
        if(B.Style<0)B.Style=ResolveStyle(unsigned(rand()));
        if(B.AimVar<=0)B.AimVar=0.88f+float(rand()%25)*0.01f; // Phase 12: persistent per-bot aim identity (0.88-1.12)
        auto Profile=TierProfile(B.Skill);
        // Teammate bots decide and build at Hard, but shoot (spread, fire rate) at the selected difficulty.
        if(B.AimSkill>=0){auto Aim=TierProfile(B.AimSkill);Profile.Spread=Aim.Spread;Profile.FireInterval=Aim.FireInterval;}
        return Profile;
    }
    // Difficulty tier for everything aim-related (hit chance, reaction, burst gaps, edit-to-shot).
    inline int AimTier(Bot& B){BotSkill(B);int T=B.AimSkill>=0?B.AimSkill:B.Skill;return (B.Pro&&T>=3)?4:T;}
    // Bots on a real player's team (Fill, party bots, legacy squads) use the Hard-tier decision making:
    // build fights, box defense, piece control, 90s, edit peeks, faster decisions. Their aim, reaction and
    // fire rate stay at the selected difficulty. Restored when the bot leaves the player's team.
    inline void UpdateTeammateSkill(Bot& B){
        const bool Mate=B.FillOriginalTeam>=0 && B.FillOriginalTeam!=50;
        if(Mate && B.AimSkill<0){BotSkill(B);B.AimSkill=B.Skill;if(B.Skill<3){B.Skill=3;AppendBotLog("squad: teammate bot uses Hard-tier decisions (aim stays at the selected difficulty)\n");}}
        else if(!Mate && B.AimSkill>=0){B.Skill=B.AimSkill;B.AimSkill=-1;}
    }
    inline AFortPlayerControllerAthena* HumanSquadLeader(const Bot& B){
        if(B.FillOriginalTeam<0 || !B.State)return nullptr;
        auto W=UWorld::GetWorld();auto Net=W?(UNetDriver*)W->NetDriver:nullptr;
        if(Net)for(auto C:Net->ClientConnections){auto PC=C?C->PlayerController:nullptr;auto PS=PC?(AFortPlayerStateAthena*)PC->PlayerState:nullptr;
            if(PS && !PS->bActorIsBeingDestroyed && PS->TeamIndex==B.State->TeamIndex && (PC->IsInAircraft() || (PC->MyFortPawn && !PC->MyFortPawn->bActorIsBeingDestroyed && (PC->MyFortPawn->GetHealth()>0 || PC->MyFortPawn->IsDBNO()))))return PC;}
        return nullptr;
    }

