    inline float BotSprintSpeed() { return (LegacyCertBotSeason() || VersionInfo.FortniteVersion==3.5) ? 600.f : 800.f; }

    inline void RequestSprint(Bot& B)
    {
        if(!B.Pawn || B.Pawn->IsDBNO() || B.Eliminated)return;
        // Season 4's player sprint ability rejects an AI controller (it has
        // no owning client). Set the replicated native movement style instead.
        // CharacterMovement still integrates acceleration, gravity and collision.
        if (B.Pawn && (VersionInfo.FortniteVersion < 5.0 || Season5Like()))
        {
            // Initialize this bot's scalar attributes without copying another
            // player's modifiers, clamping state, or temporary movement effects.
            if (!B.MovementInitialized){
                auto MO=B.Pawn->GetOffset("MovementSet");auto Set=MO!=uint32(-1)?GetFromOffset<UObject*>(B.Pawn,MO):nullptr;
                auto Type=FindStruct("FortGameplayAttributeData");int Written=0;
                if(Set && Type)for(auto Entry:{std::pair<const char*,float>{"WalkSpeed",200.f},{"RunSpeed",600.f},{"SprintSpeed",BotSprintSpeed()},{"FlySpeed",600.f},{"SpeedMultiplier",1.f},{"BackwardSpeedMultiplier",.8f},{"GravityZScale",1.f},{"JumpHeight",200.f}}){
                    auto Prop=Set->GetProperty(Entry.first);auto Off=Set->GetOffset(Entry.first);if(!Prop || Off==uint32(-1))continue;
                    auto Size=GetFromOffset<uint32>(Prop,Offsets::ElementSize);bool Changed=false;
                    if(Size==4){memcpy((uint8*)Set+Off,&Entry.second,4);Changed=true;}
                    else for(auto Name:{"BaseValue","CurrentValue","UnclampedBaseValue","UnclampedCurrentValue"}){auto O=Type->GetOffset(Name);if(O!=uint32(-1)&&O+4<=Size){memcpy((uint8*)Set+Off+O,&Entry.second,4);Changed=true;}}
                    if(Changed)++Written;
                }
                B.MovementInitialized=Written>=4;
                if(B.MovementInitialized)AppendBotLog("movement: initialized independent bot run/sprint attributes\n");
            }
            auto StyleOffset = B.Pawn->GetOffset("CurrentMovementStyle");
            auto Styles = FindEnum("EFortMovementStyle");
            const bool Aiming=B.Pawn->HasbIsTargeting() && B.Pawn->bIsTargeting;
            auto Sprint = Styles ? Styles->GetValue(Aiming?"Walking":"Sprinting") : -1;
            if (StyleOffset != (uint32)-1 && Sprint >= 0 && Sprint < 256)
            {
                if(GetFromOffset<uint8>(B.Pawn, StyleOffset)!=static_cast<uint8>(Sprint)){
                    GetFromOffset<uint8>(B.Pawn, StyleOffset)=static_cast<uint8>(Sprint);B.Pawn->ForceNetUpdate();
                }
            }
            return;
        }
        auto ASC = B.State ? B.State->AbilitySystemComponent : nullptr;
        if (!ASC || !B.Pawn || B.Pawn->IsSprinting()) return;
        auto& Items = ASC->ActivatableAbilities.Items;
        static bool LoggedAbilities = false;
        for (int I = 0; I < Items.Num(); ++I)
        {
            auto& Spec = Items.Get(I, FGameplayAbilitySpec::Size());
            if (!Spec.Ability) continue;
            auto Name = Spec.Ability->Class->Name.ToString();
            if (!LoggedAbilities) AppendBotLog((std::string("ability=") + Name.c_str() + "\n").c_str());
            if (Name.find("Sprint") == std::string::npos) continue;
            Spec.InputPressed = true;
            // Use the gameplay ability to set sprint tags/speed/animation;
            // never manufacture speed by overwriting physics velocity.
            auto Fn = ASC->GetFunction("TryActivateAbilityByClass");
            if (Fn)
            {
                auto Activated = ASC->Call<bool>(Fn, Spec.Ability->Class, false);
                if (!LoggedAbilities) AppendBotLog(Activated ? "sprint activation accepted\n" : "sprint activation rejected\n");
            }
            else if (InternalTryActivateAbility_)
            {
                FPredictionKey Key{};
                UAbilitySystemComponent::InternalServerTryActivateAbility(ASC, Spec.Handle, true, &Key, nullptr);
                if (!LoggedAbilities) AppendBotLog("sprint requested through native ability path\n");
            }
        }
        if (!LoggedAbilities)
        {
            AppendBotLog(("ability count=" + std::to_string(Items.Num()) + "\n").c_str());
            for (UObject* Object : { (UObject*)B.Pawn, (UObject*)B.Pawn->CharacterMovement })
                for (const UStruct* Class = Object->Class; Class; Class = Class->GetSuper())
                    for (auto Field = Class->GetChildren(); Field; Field = Field->GetNext())
                    {
                        auto N = Field->Name.ToString();
                        if (N.find("Sprint") != std::string::npos || N.find("Movement") != std::string::npos || N.find("Speed") != std::string::npos)
                            AppendBotLog((std::string("movement field=") + N.c_str() + "\n").c_str());
                    }
            LoggedAbilities = true;
        }
    }

    // Verify + repair the replicated CharacterParts array on a bot's player
    // state. The client builds the visible body from these parts; if any are
    // missing, the pawn renders invisible (floating pickaxe). This both
    // diagnoses (the "bad=" field on the tick log) and self-heals (re-writes
    // the array and forces a replication, which triggers the client's part
    // rebuild) so a bot can never stay invisible.
    inline bool BotPartsValid(AFortPlayerStateAthena* State)
    {
        if (!State) return false;
        auto StructOff = State->GetOffset("CharacterParts", 0x100000);
        const UObject* (*Parts)[0x6] = nullptr;
        if (StructOff != (uint32)-1)
        {
            static auto InteriorOffset = FCustomCharacterParts::StaticStruct()->GetOffset("Parts");
            if (InteriorOffset == (uint32)-1) return false;
            auto& Ccp = GetFromOffset<FCustomCharacterParts>(State, StructOff);
            Parts = &GetFromOffset<const UObject*[0x6]>(&Ccp, InteriorOffset);
        }
        else
        {
            auto Off = State->GetOffset("CharacterParts");
            if (Off == (uint32)-1) Off = State->GetOffset("LocalCharacterParts");
            if (Off == (uint32)-1) return false;
            Parts = &GetFromOffset<const UObject*[0x6]>(State, Off);
        }
        return Parts && Parts[0][0] && Parts[0][1];
    }

    inline void HealBotParts(AFortPlayerStateAthena* State)
    {
        if (!State || BotPartsValid(State)) return;
        auto PartClass = FindClass("CustomCharacterPart");
        if (!PartClass) return;
        static auto Head = LoadBotAsset(L"/Game/Characters/CharacterParts/Female/Medium/Heads/F_Med_Head1.F_Med_Head1", PartClass);
        static auto Body = LoadBotAsset(L"/Game/Characters/CharacterParts/Female/Medium/Bodies/F_Med_Soldier_01.F_Med_Soldier_01", PartClass);
        static auto Backpack = LoadBotAsset(L"/Game/Characters/CharacterParts/Backpacks/NoBackpack.NoBackpack", PartClass);
        if (!Head || !Body) return;

        auto StructOff = State->GetOffset("CharacterParts", 0x100000);
        if (StructOff != (uint32)-1)
        {
            static auto InteriorOffset = FCustomCharacterParts::StaticStruct()->GetOffset("Parts");
            if (InteriorOffset != (uint32)-1)
            {
                auto& Ccp = GetFromOffset<FCustomCharacterParts>(State, StructOff);
                auto& CharacterParts = GetFromOffset<const UObject*[0x6]>(&Ccp, InteriorOffset);
                CharacterParts[0] = Head; CharacterParts[1] = Body; CharacterParts[3] = Backpack;
            }
        }
        else
        {
            auto Off = State->GetOffset("CharacterParts");
            if (Off == (uint32)-1) Off = State->GetOffset("LocalCharacterParts");
            if (Off != (uint32)-1)
            {
                auto& CharacterParts = GetFromOffset<const UObject*[0x6]>(State, Off);
                CharacterParts[0] = Head; CharacterParts[1] = Body; CharacterParts[3] = Backpack;
            }
        }
        State->ForceNetUpdate();
    }

    // ----- POI landing (bus phase) -------------------------------------------
    //
    // The game itself treats BuildingFoundation actors as POI markers: the
    // battle royale phase logic picks a safe-zone center from them
    // (UsePOIStormCenter). So the landing targets come from the foundations
    // present in the world. When the bus takes off the game destroys every
    // bot pawn and parks its controller in the aircraft; the bot then gets a
    // fresh skydiving pawn above its POI, steers towards it and enforces a
    // strong downward velocity so it reaches the ground fast.
    inline std::vector<FVector> PoiSpots;
    inline bool PoiSpotsScanned = false;
    inline float PoiScanDelay = 0.f;
    inline int LandingSpawnsThisTick = 0; // pc limit of dive-pawn spawns per tick

    inline void TryScanPoiSpots(float DeltaSeconds)
    {
        if (PoiSpotsScanned) return;
        PoiScanDelay -= DeltaSeconds;
        if (PoiScanDelay > 0.f) return;
        PoiScanDelay = 3.f; // retry until the main map foundations are in

        TArray<ABuildingFoundation*> Found;
        Utils::GetAll<ABuildingFoundation>(Found);
        int Count = Found.Num();
        PoiSpots.clear();
        // Keep well-spread foundation spots so one survives per POI cluster.
        for (int N = 0; N < Count; ++N)
        {
            if (!Found[N]) continue;
            auto Loc = Found[N]->K2_GetActorLocation();
            bool Dup = false;
            for (auto& S : PoiSpots)
            {
                double SX = S.X - Loc.X, SY = S.Y - Loc.Y;
                if (SX * SX + SY * SY < 2000000.0) { Dup = true; break; } // ~1414 uu
            }
            if (Dup) continue;
            PoiSpots.push_back(Loc);
        }
        Found.Free();

        if ((int)PoiSpots.size() >= 3)
        {
            PoiSpotsScanned = true;
            char Line[256];
            snprintf(Line, sizeof(Line), "poispots found=%d poi=%d\n", Count, (int)PoiSpots.size());
            AppendBotLog(Line);
        }
        else
            PoiSpots.clear(); // main map still streaming in; try again later
    }

    inline uint8 BotMoveMode(RoamingMovement* Movement)
    {
        static int32 MMOff = -2;
        if (Movement && MMOff == -2) MMOff = (int32)Movement->GetOffset("MovementMode", 0);
        return (Movement && MMOff >= 0) ? GetFromOffset<uint8>(Movement, MMOff) : 255;
    }

    // Spawn island roam bounds: the bounding box of the map's player starts
    // (they are scattered across the whole spawn island), computed once.
    // Bots pick distant targets inside this box so they cross the island
    // instead of looping in little circles around their spawn point.
    inline bool HasRoamBounds = false;
    inline float RoamMinX = 0.f, RoamMaxX = 0.f, RoamMinY = 0.f, RoamMaxY = 0.f;
    // Every player-start transform on the spawn island, kept with its Z: the
    // starts provide destinations. CharacterMovement handles the actual
    // floor height and collision throughout each journey.
    inline std::vector<FVector> StartSpots;

    inline void UpdateRoamBounds()
    {
        if (HasRoamBounds) return;
        TArray<AActor*> Starts;
        Utils::GetAll(FindClass("PlayerStart"), Starts);
        int Count = Starts.Num();
        if (Count <= 0)
        {
            Starts.Free();
            return;
        }
        StartSpots.clear();
        // Season X places extra PlayerStarts across the whole island. Keep only
        // the densest cluster (the spawn island) so the map is not treated as
        // spawn island and every chest/POI excluded from landing.
        std::vector<FVector> All;
        for (int N = 0; N < Count; ++N) if (Starts[N]) All.push_back(Starts[N]->K2_GetActorLocation());
        size_t BestIndex = 0; int BestCount = -1;
        for (size_t I = 0; I < All.size(); ++I) { int C = 0; for (auto& O : All) { double DX = O.X - All[I].X, DY = O.Y - All[I].Y; if (DX * DX + DY * DY < 20000.0 * 20000.0) ++C; } if (C > BestCount) { BestCount = C; BestIndex = I; } }
        std::vector<FVector> Island;
        if (!All.empty()) for (auto& O : All) { double DX = O.X - All[BestIndex].X, DY = O.Y - All[BestIndex].Y; if (DX * DX + DY * DY < 25000.0 * 25000.0) Island.push_back(O); }
        Count = (int)Island.size();
        for (int N = 0; N < Count; ++N)
        {
            auto Loc = Island[N];
            StartSpots.push_back(Loc);
            if (N == 0)
            {
                RoamMinX = RoamMaxX = (float)Loc.X;
                RoamMinY = RoamMaxY = (float)Loc.Y;
            }
            else
            {
                if ((float)Loc.X < RoamMinX) RoamMinX = (float)Loc.X;
                if ((float)Loc.X > RoamMaxX) RoamMaxX = (float)Loc.X;
                if ((float)Loc.Y < RoamMinY) RoamMinY = (float)Loc.Y;
                if ((float)Loc.Y > RoamMaxY) RoamMaxY = (float)Loc.Y;
            }
        }
        Starts.Free();
        // Pad a little so legs can reach past the outermost starts.
        RoamMinX -= 500.f; RoamMaxX += 500.f;
        RoamMinY -= 500.f; RoamMaxY += 500.f;
        HasRoamBounds = true;
        char Line[256];
        snprintf(Line, sizeof(Line), "roambounds starts=%d box=%.0f,%.0f..%.0f,%.0f span=%.0fx%.0f\n",
            Count, RoamMinX, RoamMinY, RoamMaxX, RoamMaxY,
            RoamMaxX - RoamMinX, RoamMaxY - RoamMinY);
        AppendBotLog(Line);
    }

    // Syndicate Studio (Dev Kit): TILTED_STUDIO=1 from the launcher. The match stays on the warm-up island for good (no
    // bus, no storm) so the map can be edited live; the launcher also starts it with no bots.
    inline bool StudioMode(){static const bool On=[]{wchar_t V[4]{};return GetEnvironmentVariableW(L"TILTED_STUDIO",V,4)==1 && V[0]==L'1';}();return On;}
    inline void StudioHoldWarmup(AFortGameStateAthena* GameState,float Now){
        if(!GameState || !GameState->HasWarmupCountdownEndTime())return;
        // Ten minutes ahead, pushed forward every tick: the countdown never reaches zero, so nothing starts the bus.
        if(GameState->WarmupCountdownEndTime<Now+590.f){GameState->WarmupCountdownStartTime=Now;GameState->WarmupCountdownEndTime=Now+600.f;GameState->ForceNetUpdate();}
    }
    inline int DesiredBotCount()
    {
        static int Count = -1;
        if (Count < 0)
        {
            Count = 99; // One human plus 99 staggered Season 4 bots.
            wchar_t Value[16]{};
            if (GetEnvironmentVariableW(L"TILTED_BOT_COUNT", Value, 16))
                Count = _wtoi(Value);
            if (Count < 0) Count = 0;
            if (Count > 99) Count = 99;
        }
        return Count;
    }

    inline bool IsBot(UObject* Player)
    {
        for (auto& Bot : Bots)
            if (Bot.Controller == Player) return true;
        return false;
    }

    // A real (non-bot) player is joining while there is a client connection
    // whose controller has no pawn yet. Pause new movement input during that
    // initial replication burst so joining clients can finish loading.
    inline bool RealJoinInProgress()
    {
        auto World = UWorld::GetWorld();
        auto Driver = World ? (UNetDriver*)World->NetDriver : nullptr;
        if (!Driver) return false;
        for (auto& Conn : Driver->ClientConnections)
        {
            if (!Conn || !Conn->PlayerController) continue;
            if (!Conn->PlayerController->MyFortPawn)
                return true;
        }
        return false;
    }

    // 0 = warmup assets are not streamed in yet, 1 = spawned, 2 = failed (retry)
    // Location of the real (non-bot) player, so bots can appear right next to the
    // human instead of at an arbitrary PlayerStart the player cannot see.
    inline bool HumanPlayerLocation(FVector& Out)
    {
        auto World = UWorld::GetWorld();
        auto Net=World?(UNetDriver*)World->NetDriver:nullptr;
        if(!Net)return false;
        // Only an actual network connection can arm a match. Local host and bot
        // roster controllers are not proof that a human readied up.
        for(auto Conn:Net->ClientConnections){
            auto PC=Conn?Conn->PlayerController:nullptr;
            auto PS=PC?(AFortPlayerStateAthena*)PC->PlayerState:nullptr;
            if(!PS || (PS->HasbIsABot() && PS->bIsABot) || PS->bIsSpectator)continue;
            auto Pawn=PC->MyFortPawn;
            if(!Pawn || Pawn->bActorIsBeingDestroyed || Pawn->GetHealth()<=0)continue;
            Out=Pawn->K2_GetActorLocation();return true;
        }
        return false;
    }

    // Do not launch the bus while another connected client is still creating its pawn.
    inline bool ConnectedHumansReady()
    {
        auto World=UWorld::GetWorld();auto Net=World?(UNetDriver*)World->NetDriver:nullptr;
        if(!Net)return false;
        bool Any=false;
        for(auto Conn:Net->ClientConnections){
            if(!Conn)continue;
            auto PC=Conn->PlayerController;
            auto PS=PC?(AFortPlayerStateAthena*)PC->PlayerState:nullptr;
            if(!PS)return false;
            if((PS->HasbIsABot() && PS->bIsABot) || PS->bIsSpectator)continue;
            auto Pawn=PC->MyFortPawn;
            if(!Pawn || Pawn->bActorIsBeingDestroyed || Pawn->GetHealth()<=0)return false;
            Any=true;
        }
        return Any;
    }

    inline double FlatDistance(FVector A, FVector B)
    {
        auto X = A.X - B.X, Y = A.Y - B.Y;
        return sqrt(X * X + Y * Y);
    }

    inline void RenameBot(Bot& B);
    // Bot teammates (bots on a real player's team) always get a name from the full-name list, never one of the six
    // fixed names, never another bot's, and not one used for a teammate in recent matches (the last 120 are kept in
    // Runtime/Server/teammate-names.txt), so every match feels like new players.
    inline bool ForceTeammateName=false;
    inline std::unordered_set<void*> TeammateNamed;inline UWorld* TeammateNamedWorld=nullptr;
    inline bool OnHumanTeam(AFortPlayerStateAthena* State){
        if(!State || State->TeamIndex<3)return false;auto W=UWorld::GetWorld();auto Net=W?(UNetDriver*)W->NetDriver:nullptr;if(!Net)return false;
        for(auto Conn:Net->ClientConnections){auto PC=Conn?Conn->PlayerController:nullptr;auto PS=PC?(AFortPlayerStateAthena*)PC->PlayerState:nullptr;
            if(PS && PS!=State && PS->TeamIndex==State->TeamIndex)return true;}
        return false;
    }
    inline std::filesystem::path TeammateHistoryFile(){wchar_t Ready[32768]{};if(!GetEnvironmentVariableW(L"TILTED_SERVER_READY_FILE",Ready,32768))return {};return std::filesystem::path(Ready).parent_path()/L"teammate-names.txt";}
    inline std::vector<std::wstring>& TeammateHistory(){
        static std::vector<std::wstring> List;static bool Loaded=false;
        if(!Loaded){Loaded=true;auto File=TeammateHistoryFile();if(!File.empty()){std::ifstream In(File,std::ios::binary);std::string Line;
            while(std::getline(In,Line)){while(!Line.empty()&&(Line.back()=='\r'||Line.back()=='\n'))Line.pop_back();if(Line.empty())continue;
                int N=MultiByteToWideChar(CP_UTF8,0,Line.data(),int(Line.size()),nullptr,0);std::wstring W(size_t(N>0?N:0),L'\0');if(N>0)MultiByteToWideChar(CP_UTF8,0,Line.data(),int(Line.size()),W.data(),N);List.push_back(W);}}}
        return List;
    }
    inline void RememberTeammateName(const std::wstring& Name){
        auto& List=TeammateHistory();List.push_back(Name);if(List.size()>120)List.erase(List.begin(),List.begin()+(List.size()-120));
        auto File=TeammateHistoryFile();if(File.empty())return;std::ofstream Out(File,std::ios::binary|std::ios::trunc);
        for(auto& W:List){int N=WideCharToMultiByte(CP_UTF8,0,W.data(),int(W.size()),nullptr,0,nullptr,nullptr);std::string U(size_t(N>0?N:0),'\0');if(N>0)WideCharToMultiByte(CP_UTF8,0,W.data(),int(W.size()),U.data(),N,nullptr,nullptr);Out<<U<<"\n";}
    }
    // Once a second until the bus leaves: a bot that joined a real player's team after it was named (team fill) gets a
    // teammate name too.
    inline void NameHumanTeammates(UWorld* World,float DT){
        static float Next=0;Next-=DT;if(Next>0)return;Next=1.f;
        if(TeammateNamedWorld!=World){TeammateNamedWorld=World;TeammateNamed.clear();}
        for(auto& B:Bots){
            if(B.Eliminated || !B.State || TeammateNamed.count(B.State) || !OnHumanTeam(B.State))continue;
            ForceTeammateName=true;RenameBot(B);ForceTeammateName=false;
            char L[160];snprintf(L,sizeof(L),"names: bot teammate named %ls\n",B.DisplayName.c_str());AppendBotLog(L);
        }
        // A bot teammate in the default outfit (it was put on your team after it spawned): a real skin, pickaxe and
        // glider instead.
        for(auto& B:Bots){
            if(B.Eliminated || !B.State || !B.Pawn || B.Pawn->bActorIsBeingDestroyed || !B.DefaultCosmetics || !OnHumanTeam(B.State))continue;
            B.DefaultCosmetics=false;B.PickaxeSkin=nullptr;B.GliderSkin=nullptr;B.PickaxeDefinition=nullptr;
            SelectRandomOutfit(false);SaveBotOutfit(B);RestoreBotOutfit(B);
            char L[160];snprintf(L,sizeof(L),"outfits: bot teammate %ls got a skin (was the default outfit)\n",B.DisplayName.c_str());AppendBotLog(L);
        }
    }
