        const bool IntroPlaylist=wcsstr(FConfiguration::Playlist,L"Intro_Apollo")!=nullptr;
        if(B.BusTime>(IntroPlaylist?420.f:150.f)){RemoveFailedBusBot(B);return;}
        if(!B.bLanding && !B.BusPrepared && B.Pawn && !B.Pawn->bActorIsBeingDestroyed){
            // AI drivers own the warmup pawn, so native player bus cleanup may miss it.
            if(auto Hide=B.Pawn->GetFunction("SetActorHiddenInGame"))B.Pawn->Call<void>(Hide,true);
            if(auto Collision=B.Pawn->GetFunction("SetActorEnableCollision"))B.Pawn->Call<void>(Collision,false);
            B.Pawn->bCanBeDamaged=true;B.Pawn->ForceNetUpdate();B.BusPrepared=true;
        }
