            // Use the replicated aircraft window, not time since entering the bus phase.
            const float Now=(float)UGameplayStatics::GetTimeSeconds(UWorld::GetWorld());
            if(!NoBus && (!Aircraft->HasDropStartTime() || !Aircraft->HasDropEndTime()) && !IntroPlaylist)return;
            float Open=NoBus?Now:Aircraft->DropStartTime, Close=NoBus?Now+1.f:Aircraft->DropEndTime;
            // Chapter 2 entrance: the intro's movie skydives the players itself and never opens a normal drop
