                            if(!ProbeGround(B.Pawn,Top,Low,30,H,G,N,&Surf) || !H || N.Z<.6f){++WetRejects;return false;}
                            if(Surf){auto Nm=Surf->Name.ToString()+Surf->Class->Name.ToString();
                                if(Nm.find("Water")!=std::string::npos || Nm.find("water")!=std::string::npos || Nm.find("Lava")!=std::string::npos || Nm.find("lava")!=std::string::npos){++WetRejects;return false;}}
