        auto Ability=BotThrowableAbility(B,Kind);auto Radius=Grenade->GetOffset("ExplosionRadius");auto AR=Ability?Ability->GetOffset("ExplosionRadius"):uint32(-1);
        if(Radius!=uint32(-1) && AR!=uint32(-1) && GetFromOffset<float>(Ability,AR)>0)GetFromOffset<float>(Grenade,Radius)=GetFromOffset<float>(Ability,AR);
