                    auto R = Angle * Bot.DetourSide * 3.14159265f / 180.f;
                    FVector Candidate{};
                    Candidate.X = Direction.X * cos(R) - Direction.Y * sin(R);
                    Candidate.Y = Direction.X * sin(R) + Direction.Y * cos(R);
                    // Short lateral/backward detours are necessary around walls even during rotation.
                    if (!WalkableAhead(Bot.Pawn, Location, Candidate, Bot.RampPushTime>0?RampLook:(Looting && Distance<450)?float((std::max)(70.0,(std::min)(180.0,Distance-80))):280.f, Bot.RampPushTime<=0)) continue;
                    if(Bot.ExperienceLeg.empty()){Bot.ExperienceLeg=RouteMemory(Location,Candidate);Bot.ExperienceStart=Location;Bot.ExperienceAge=0;}
                    Bot.SafeDirection = Candidate; Bot.SafeToMove = true; Bot.HeadingHold = Angle == 0.f ? .6f : 2.f;
                    break;
