                const bool Busy=Bot.Harvesting || Bot.ReviveTarget.Get() || Bot.Heal.Using!=SyndicateSustain::Item::None || Bot.BuildModeTime>0
                    || Bot.HoldBoxed || Bot.PanicFaces>0 || (Bot.Enemy.Get() && Bot.EnemyVisible) || Bot.EscapeTime>0 || Bot.Pawn->IsDBNO();
                const bool Travelling=FlatDistance(Location,Bot.Target)>700;
                if(FlatDistance(Location,Bot.ProgressAnchor)>=500){Bot.ProgressAnchor=Location;Bot.NoProgress=0;}
                else if(Travelling && !Busy)Bot.NoProgress+=Bot.StuckTime;
