        if(FullNavigation && !Fighting){if(B.RampPushTime>0)B.Target=B.RampPushTarget;UpdateBotNavigation(B,Tick,true,B.Pursuing || B.RampPushTime>0);}if(B.Shots && FirstShot<0)FirstShot=Elapsed;
        if(Advance && !FullNavigation && B.Pursuing && B.RampPushTime>0){auto P=B.Pawn->K2_GetActorLocation();auto D=B.RampPushTarget-P;auto Distance=FlatDistance(P,B.RampPushTarget);if(Distance>1){D.X/=Distance;D.Y/=Distance;D.Z=0;if(WalkableAhead(B.Pawn,P,D,float((std::max)(30.0,(std::min)(180.0,Distance))),false))B.Pawn->AddMovementInput(D,1.f,true);}}
        if(Advance){auto P=B.Pawn->K2_GetActorLocation();if(FlatDistance(P,LastSample)<2)Still+=Tick;else Still=0;LongestStill=(std::max)(LongestStill,Still);LastSample=P;}
