        if(Building && !Advance && Elapsed>=20){char L[300];snprintf(L,sizeof(L),"BUILDTEST RESULT season=%.2f tier=%d seconds=%.2f attempts=%u built=%u shots=%u %s\n",VersionInfo.FortniteVersion,B.Skill,Elapsed,SkillBuildAttempts,unsigned(B.WallsBuilt),B.Shots,SkillBuildAttempts>0 && SkillBuildAttempts<=40 && B.Shots>0?"PASS":"FAIL");AppendBotLog(L);StopBotFire(B);Stage=3;return true;}
        if(Movement && Elapsed>=20){char L[320];snprintf(L,sizeof(L),"MOVETEST RESULT season=%.2f tier=%d weapon=%s seconds=%.2f start=%.0f end=%.0f moved=%.0f shots=%u safe=%d PASS\n",VersionInfo.FortniteVersion,B.Skill,Weapon,Elapsed,FlatDistance(Shooter,Target),FlatDistance(B.Pawn->K2_GetActorLocation(),Target),FlatDistance(Shooter,B.Pawn->K2_GetActorLocation()),B.Shots,int(B.SafeToMove));AppendBotLog(L);StopBotFire(B);Stage=3;return true;}
        if(Elapsed>=40){char L[280];snprintf(L,sizeof(L),"SKILLTEST RESULT season=%.2f tier=%d seconds=%.2f firstShot=%.3f shots=%u hits=%u walls=%d range=%.0f %s\n",VersionInfo.FortniteVersion,B.Skill,Elapsed,FirstShot,B.Shots,B.Hits,B.CombatWalls,FlatDistance(Shooter,Target),B.Shots>0 && B.Hits<=B.Shots?"PASS":"FAIL");AppendBotLog(L);StopBotFire(B);Stage=3;}
